CREATE TABLE IF NOT EXISTS "ubec_main"."reciprocity_transactions" (
    "id" integer NOT NULL DEFAULT nextval('reciprocity_transactions_id_seq'::regclass),
    "account_id" varchar(56) NOT NULL,
    "transaction_type" varchar(20) NOT NULL,
    "amount" numeric(18,8) NOT NULL,
    "reason" text,
    "source" varchar(50),
    "context" jsonb,
    "created_at" timestamp NOT NULL DEFAULT now(),
    PRIMARY KEY ("id"),
    CHECK (((transaction_type)::text = ANY ((ARRAY['credit'::character varying, 'debit'::character varying, 'adjustment'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."regenerative_projects" (
    "id" integer NOT NULL DEFAULT nextval('regenerative_projects_id_seq'::regclass),
    "agent_id" integer NOT NULL,
    "project_name" varchar(255) NOT NULL,
    "description" text,
    "project_type" varchar(100) NOT NULL,
    "verification_status" varchar(50) DEFAULT 'unverified'::character varying,
    "verification_date" timestamptz,
    "impact_metrics" jsonb,
    "metadata" jsonb,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("id"),
    CHECK (((verification_status)::text = ANY ((ARRAY['unverified'::character varying, 'pending'::character varying, 'verified'::character varying, 'rejected'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."scheduler_execution_log" (
    "id" integer NOT NULL DEFAULT nextval('scheduler_execution_log_id_seq'::regclass),
    "job_name" varchar(100) NOT NULL,
    "executed_at" timestamptz NOT NULL DEFAULT now(),
    "duration_ms" integer,
    "success" boolean NOT NULL,
    "error_message" text,
    "error_traceback" text,
    "created_at" timestamptz DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."scheduler_jobs" (
    "id" integer NOT NULL DEFAULT nextval('scheduler_jobs_id_seq'::regclass),
    "job_name" varchar(100) NOT NULL,
    "schedule_interval" varchar(50) NOT NULL,
    "next_run" timestamptz NOT NULL,
    "last_run" timestamptz,
    "job_function" text NOT NULL,
    "parameters" jsonb,
    "enabled" boolean DEFAULT true,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("id"),
    UNIQUE ("job_name"),
    CHECK ((next_run > created_at))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."schema_migrations" (
    "migration_id" integer NOT NULL DEFAULT nextval('schema_migrations_migration_id_seq'::regclass),
    "migration_name" varchar(255) NOT NULL,
    "applied_at" timestamptz NOT NULL DEFAULT now(),
    "applied_by" varchar(100) NOT NULL,
    "description" text,
    "checksum" varchar(64),
    "execution_time_ms" integer,
    "status" varchar(20) NOT NULL DEFAULT 'completed'::character varying,
    "error_message" text,
    "rollback_script" text,
    PRIMARY KEY ("migration_id"),
    UNIQUE ("migration_name"),
    CHECK (((status)::text = ANY ((ARRAY['completed'::character varying, 'failed'::character varying, 'rolled_back'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."stellar_accounts" (
    "id" integer NOT NULL DEFAULT nextval('stellar_accounts_id_seq'::regclass),
    "account_id" varchar(56) NOT NULL,
    "primary_element" text,
    "token_holdings" text[],
    "sequence" bigint,
    "subentry_count" integer DEFAULT 0,
    "inflation_destination" varchar(56),
    "home_domain" varchar(255),
    "thresholds" jsonb,
    "flags" jsonb,
    "signers" jsonb,
    "created_at" timestamptz,
    "last_modified_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "last_activity_at" timestamptz,
    "sync_status" varchar(20) DEFAULT 'pending'::character varying,
    "sync_cursor" varchar(100),
    "metadata" jsonb,
    PRIMARY KEY ("id"),
    UNIQUE ("account_id"),
    CHECK ((length((account_id)::text) = 56))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."stellar_effects" (
    "id" integer NOT NULL DEFAULT nextval('stellar_effects_id_seq'::regclass),
    "effect_id" varchar(100) NOT NULL,
    "operation_id" varchar(100) NOT NULL,
    "effect_element" text,
    "type" varchar(50) NOT NULL,
    "account" varchar(56),
    "amount" numeric(20,7),
    "asset_type" varchar(20),
    "asset_code" text,
    "asset_issuer" varchar(56),
    "details" jsonb,
    "created_at" timestamptz NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("effect_id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."stellar_offers" (
    "id" integer NOT NULL DEFAULT nextval('stellar_offers_id_seq'::regclass),
    "offer_id" bigint NOT NULL,
    "seller_account" varchar(56) NOT NULL,
    "selling_asset" text,
    "buying_asset" varchar(12) NOT NULL,
    "amount" numeric(20,7) NOT NULL,
    "price" numeric(20,7) NOT NULL,
    "price_r_n" integer,
    "price_r_d" integer,
    "side" varchar(4) NOT NULL,
    "is_passive" boolean DEFAULT false,
    "last_modified_ledger" bigint,
    "last_modified_time" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    "status" varchar(20) DEFAULT 'active'::character varying,
    PRIMARY KEY ("id"),
    UNIQUE ("offer_id"),
    CHECK (((side)::text = ANY ((ARRAY['buy'::character varying, 'sell'::character varying])::text[]))),
    CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'filled'::character varying, 'cancelled'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."stellar_operations" (
    "id" integer NOT NULL DEFAULT nextval('stellar_operations_id_seq'::regclass),
    "operation_id" varchar(100) NOT NULL,
    "transaction_hash" varchar(64) NOT NULL,
    "operation_element" text,
    "asset_code" text,
    "type" text NOT NULL,
    "type_i" integer,
    "source_account" varchar(56),
    "amount" numeric(20,7),
    "asset_type" varchar(20),
    "asset_issuer" varchar(56),
    "from_account" varchar(56),
    "to_account" varchar(56),
    "details" jsonb,
    "created_at" timestamptz NOT NULL,
    "metadata" jsonb,
    "exchange_source_asset" varchar(12),
    "exchange_source_amount" numeric(18,8),
    "exchange_dest_asset" varchar(12),
    "exchange_dest_amount" numeric(18,8),
    PRIMARY KEY ("id"),
    UNIQUE ("operation_id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."stellar_transactions" (
    "id" integer NOT NULL DEFAULT nextval('stellar_transactions_id_seq'::regclass),
    "transaction_hash" varchar(64) NOT NULL,
    "ledger_sequence" bigint NOT NULL,
    "primary_element" text,
    "involves_tokens" text[],
    "source_account" varchar(56) NOT NULL,
    "source_account_sequence" bigint,
    "fee_charged" bigint,
    "max_fee" bigint,
    "operation_count" integer,
    "time_bounds" jsonb,
    "memo_type" varchar(20),
    "memo" varchar(255),
    "successful" boolean DEFAULT true,
    "result_code" text,
    "result_xdr" text,
    "created_at" timestamptz NOT NULL,
    "ledger_close_time" timestamptz,
    "metadata" jsonb,
    "ledger" bigint,
    PRIMARY KEY ("id"),
    UNIQUE ("transaction_hash")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."sync_jobs" (
    "id" integer NOT NULL DEFAULT nextval('sync_jobs_id_seq'::regclass),
    "job_type" varchar(50) NOT NULL,
    "schedule_interval" interval NOT NULL,
    "last_run" timestamptz,
    "next_run" timestamptz NOT NULL,
    "enabled" boolean DEFAULT true,
    "parameters" jsonb,
    "last_status" varchar(20),
    "error_message" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."sync_status" (
    "account_id" varchar(56) NOT NULL,
    "last_sync" timestamptz NOT NULL DEFAULT now(),
    "last_block_height" bigint,
    "last_ledger_sequence" bigint,
    "last_transaction_id" varchar(64),
    "sync_count" integer DEFAULT 0,
    "status" varchar(20) DEFAULT 'active'::character varying,
    "error_count" integer DEFAULT 0,
    "last_error" text,
    "last_error_at" timestamptz,
    PRIMARY KEY ("account_id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."system_configuration" (
    "id" integer NOT NULL DEFAULT nextval('system_configuration_id_seq'::regclass),
    "parameter_name" varchar(100) NOT NULL,
    "parameter_value" text NOT NULL,
    "parameter_type" varchar(20) DEFAULT 'string'::character varying,
    "description" text,
    "is_sensitive" boolean DEFAULT false,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("id"),
    UNIQUE ("parameter_name"),
    CHECK (((parameter_type)::text = ANY ((ARRAY['string'::character varying, 'number'::character varying, 'boolean'::character varying, 'json'::character varying, 'address'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."system_settings" (
    "setting_id" integer NOT NULL DEFAULT nextval('system_settings_setting_id_seq'::regclass),
    "setting_key" varchar(100) NOT NULL,
    "setting_value" text NOT NULL,
    "setting_type" varchar(20) DEFAULT 'string'::character varying,
    "description" text,
    "category" varchar(50) DEFAULT 'general'::character varying,
    "is_active" boolean DEFAULT true,
    "is_encrypted" boolean DEFAULT false,
    "created_at" timestamp DEFAULT now(),
    "updated_at" timestamp DEFAULT now(),
    "created_by" varchar(100),
    "updated_by" varchar(100),
    PRIMARY KEY ("setting_id"),
    UNIQUE ("setting_key"),
    CHECK (((setting_type)::text = ANY ((ARRAY['string'::character varying, 'integer'::character varying, 'float'::character varying, 'boolean'::character varying, 'json'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."transfer_recommendations" (
    "id" integer NOT NULL DEFAULT nextval('transfer_recommendations_id_seq'::regclass),
    "recommendation_date" timestamp NOT NULL DEFAULT now(),
    "asset_code" varchar(12) NOT NULL,
    "asset_issuer" varchar(56) NOT NULL,
    "from_account_type" varchar(50) NOT NULL,
    "to_account_type" varchar(50) NOT NULL,
    "amount" numeric(18,8) NOT NULL,
    "status" varchar(20) NOT NULL DEFAULT 'pending'::character varying,
    "status_message" text,
    "transaction_hash" varchar(64),
    "actual_amount" numeric(18,8),
    "priority" integer DEFAULT 5,
    "created_at" timestamp NOT NULL DEFAULT now(),
    "updated_at" timestamp NOT NULL DEFAULT now(),
    "completed_at" timestamp,
    PRIMARY KEY ("id"),
    CHECK ((amount > (0)::numeric)),
    CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'cancelled'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."transformation_phases" (
    "id" integer NOT NULL DEFAULT nextval('transformation_phases_id_seq'::regclass),
    "phase_id" varchar(255) NOT NULL,
    "name" varchar(255) NOT NULL,
    "description" text NOT NULL,
    "start_date" timestamptz NOT NULL,
    "end_date" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    "target_outcomes" text[] DEFAULT '{}',
    "key_indicators" jsonb DEFAULT '{}'::jsonb,
    "participating_agents" text[] DEFAULT '{}',
    "actions_completed" integer DEFAULT 0,
    "total_ubectt_distributed" numeric(20,7) DEFAULT 0.0,
    "phase_momentum" numeric(5,4) DEFAULT 0.0,
    "is_active" boolean DEFAULT true,
    "completion_percentage" numeric(5,2) DEFAULT 0.0,
    "metadata" jsonb DEFAULT '{}'::jsonb,
    PRIMARY KEY ("id"),
    UNIQUE ("phase_id"),
    CHECK ((actions_completed >= 0)),
    CHECK (((completion_percentage >= (0)::numeric) AND (completion_percentage <= (100)::numeric))),
    CHECK (((phase_momentum >= (0)::numeric) AND (phase_momentum <= (1)::numeric))),
    CHECK ((total_ubectt_distributed >= (0)::numeric))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."transformative_actions" (
    "id" integer NOT NULL DEFAULT nextval('transformative_actions_id_seq'::regclass),
    "action_id" varchar(255) NOT NULL,
    "agent_id" varchar(56) NOT NULL,
    "action_type" text NOT NULL,
    "description" text NOT NULL,
    "impact_scale" text NOT NULL,
    "timestamp" timestamptz NOT NULL DEFAULT now(),
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    "direct_beneficiaries" integer DEFAULT 0,
    "indirect_reach" integer DEFAULT 0,
    "regeneration_score" numeric(5,4) DEFAULT 0.0,
    "catalytic_multiplier" numeric(5,4) DEFAULT 1.0,
    "verified" boolean DEFAULT false,
    "verifier_ids" text[] DEFAULT '{}',
    "evidence_urls" text[] DEFAULT '{}',
    "verification_count" integer,
    "ubectt_awarded" numeric(20,7) DEFAULT 0.0,
    "distribution_tx_hash" varchar(64),
    "reward_calculated_at" timestamptz,
    "reward_distributed_at" timestamptz,
    "tags" text[] DEFAULT '{}',
    "related_actions" text[] DEFAULT '{}',
    "metadata" jsonb DEFAULT '{}'::jsonb,
    PRIMARY KEY ("id"),
    UNIQUE ("action_id"),
    CHECK (((catalytic_multiplier >= (1)::numeric) AND (catalytic_multiplier <= (10)::numeric))),
    CHECK ((direct_beneficiaries >= 0)),
    CHECK ((indirect_reach >= 0)),
    CHECK (((regeneration_score >= (0)::numeric) AND (regeneration_score <= (1)::numeric))),
    CHECK ((ubectt_awarded >= (0)::numeric))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."ubec_audit_log" (
    "id" integer NOT NULL DEFAULT nextval('ubec_audit_log_id_seq'::regclass),
    "element" text,
    "token_code" text,
    "entity_type" varchar(50) NOT NULL,
    "entity_id" varchar(100) NOT NULL,
    "audit_type" varchar(50) NOT NULL,
    "status" varchar(20) NOT NULL,
    "is_valid" boolean DEFAULT true,
    "is_anomaly" boolean DEFAULT false,
    "anomaly_type" varchar(50),
    "severity" varchar(20),
    "audit_details" jsonb,
    "validation_rules" jsonb,
    "violations" jsonb,
    "audited_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "auditor" varchar(100),
    "metadata" jsonb,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."ubec_balances" (
    "id" integer NOT NULL DEFAULT nextval('ubec_balances_id_seq'::regclass),
    "account_id" varchar(56) NOT NULL,
    "token_code" text NOT NULL,
    "element" text NOT NULL,
    "balance" numeric(20,7) NOT NULL DEFAULT 0,
    "buying_liabilities" numeric(20,7) DEFAULT 0,
    "selling_liabilities" numeric(20,7) DEFAULT 0,
    "limit_amount" numeric(20,7),
    "is_authorized" boolean DEFAULT false,
    "is_authorized_to_maintain_liabilities" boolean DEFAULT false,
    "is_clawback_enabled" boolean DEFAULT false,
    "distribution_category" text,
    "last_modified_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "sync_timestamp" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "metadata" jsonb,
    PRIMARY KEY ("id"),
    UNIQUE ("account_id", "token_code"),
    CHECK ((balance >= (0)::numeric))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."ubec_distributions" (
    "id" integer NOT NULL DEFAULT nextval('ubec_distributions_id_seq'::regclass),
    "token_code" text NOT NULL,
    "element" text NOT NULL,
    "category" text NOT NULL,
    "target_percentage" numeric(5,2) NOT NULL,
    "current_percentage" numeric(5,2) NOT NULL,
    "current_amount" numeric(20,7) NOT NULL,
    "total_supply" numeric(20,7) NOT NULL,
    "is_compliant" boolean DEFAULT true,
    "deviation" numeric(5,2) DEFAULT 0,
    "snapshot_time" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "last_rebalance" timestamptz,
    "next_check" timestamptz,
    "metadata" jsonb,
    PRIMARY KEY ("id"),
    CHECK (((current_percentage >= (0)::numeric) AND (current_percentage <= (100)::numeric))),
    CHECK (((target_percentage >= (0)::numeric) AND (target_percentage <= (100)::numeric)))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."ubec_holonic_metrics" (
    "id" integer NOT NULL DEFAULT nextval('ubec_holonic_metrics_id_seq'::regclass),
    "account_id" varchar(56),
    "element" text,
    "principle" text NOT NULL,
    "score" numeric(5,4) NOT NULL,
    "raw_value" numeric(20,7),
    "normalized_value" numeric(5,4),
    "health_status" text,
    "assessment_details" jsonb,
    "calculation_method" varchar(100),
    "data_points" integer,
    "confidence_level" numeric(5,4),
    "calculated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "valid_until" timestamptz,
    "metadata" jsonb,
    PRIMARY KEY ("id"),
    CHECK (((normalized_value IS NULL) OR ((normalized_value >= (0)::numeric) AND (normalized_value <= (1)::numeric)))),
    CHECK (((score >= (0)::numeric) AND (score <= (1)::numeric)))
);

CREATE TABLE IF NOT EXISTS "ubec_main"."ubec_reports" (
    "id" integer NOT NULL DEFAULT nextval('ubec_reports_id_seq'::regclass),
    "element" text,
    "token_code" text,
    "report_type" varchar(50) NOT NULL,
    "title" varchar(255) NOT NULL,
    "summary" text,
    "content" jsonb NOT NULL,
    "generated_by" varchar(100),
    "report_period_start" timestamptz,
    "report_period_end" timestamptz,
    "status" varchar(20) DEFAULT 'draft'::character varying,
    "generated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "published_at" timestamptz,
    "file_path" varchar(500),
    "file_format" varchar(20),
    "metadata" jsonb,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ubec_main"."ubec_sync_status" (
    "id" integer NOT NULL DEFAULT nextval('ubec_sync_status_id_seq'::regclass),
    "element" text,
    "token_code" text,
    "sync_type" varchar(50) NOT NULL,
    "status" varchar(20) NOT NULL,
    "cursor" varchar(100),
    "last_sync_time" timestamptz,
    "next_sync_time" timestamptz,
    "records_synced" integer DEFAULT 0,
    "errors_encountered" integer DEFAULT 0,
    "duration_ms" integer,
    "sync_details" jsonb,
    "error_log" jsonb,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
    "metadata" jsonb,
    PRIMARY KEY ("id"),
    UNIQUE ("element", "token_code", "sync_type")
);

-- Foreign keys (added after all tables exist)
