ALTER TABLE "ubec_main"."agent_benefit_history" ADD FOREIGN KEY ("agent_id") REFERENCES "ubec_main"."agents" ("id");
ALTER TABLE "ubec_main"."agent_contribution_history" ADD FOREIGN KEY ("agent_id") REFERENCES "ubec_main"."agents" ("id");
ALTER TABLE "ubec_main"."agent_holon_memberships" ADD FOREIGN KEY ("agent_id") REFERENCES "ubec_main"."agents" ("id");
ALTER TABLE "ubec_main"."agent_holon_memberships" ADD FOREIGN KEY ("holon_id") REFERENCES "ubec_main"."holons" ("id");
ALTER TABLE "ubec_main"."holons" ADD FOREIGN KEY ("parent_holon_id") REFERENCES "ubec_main"."holons" ("id");
ALTER TABLE "ubec_main"."liquidity_pool_owners" ADD FOREIGN KEY ("account_id") REFERENCES "ubec_main"."stellar_accounts" ("account_id");
ALTER TABLE "ubec_main"."liquidity_pool_owners" ADD FOREIGN KEY ("liquidity_pool_id") REFERENCES "ubec_main"."liquidity_pools" ("id");
ALTER TABLE "ubec_main"."regenerative_projects" ADD FOREIGN KEY ("agent_id") REFERENCES "ubec_main"."agents" ("id");
ALTER TABLE "ubec_main"."stellar_effects" ADD FOREIGN KEY ("operation_id") REFERENCES "ubec_main"."stellar_operations" ("operation_id");
ALTER TABLE "ubec_main"."stellar_offers" ADD FOREIGN KEY ("seller_account") REFERENCES "ubec_main"."stellar_accounts" ("account_id");
ALTER TABLE "ubec_main"."stellar_operations" ADD FOREIGN KEY ("transaction_hash") REFERENCES "ubec_main"."stellar_transactions" ("transaction_hash");
ALTER TABLE "ubec_main"."stellar_transactions" ADD FOREIGN KEY ("source_account") REFERENCES "ubec_main"."stellar_accounts" ("account_id");
ALTER TABLE "ubec_main"."transformative_actions" ADD FOREIGN KEY ("agent_id") REFERENCES "ubec_main"."stellar_accounts" ("account_id");
ALTER TABLE "ubec_main"."ubec_balances" ADD FOREIGN KEY ("account_id") REFERENCES "ubec_main"."stellar_accounts" ("account_id");
ALTER TABLE "ubec_main"."ubec_holonic_metrics" ADD FOREIGN KEY ("account_id") REFERENCES "ubec_main"."stellar_accounts" ("account_id");

